/**
 * export-week-pdf Edge Function
 *
 * GET ?week_start=YYYY-MM-DD — branded PDF for the caller's week data.
 * Uses caller JWT only (no service_role). RLS applies.
 */

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";
import { PDFDocument, rgb, StandardFonts } from "npm:pdf-lib@1.17.1";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

const WEEK_START_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

const ORANGE = rgb(0xf7 / 255, 0xa2 / 255, 0x35 / 255);
const ORANGE_DARK = rgb(0xec / 255, 0x4a / 255, 0x31 / 255);
const DARK = rgb(0x1a / 255, 0x16 / 255, 0x13 / 255);
const MUTED = rgb(0x8a / 255, 0x81 / 255, 0x78 / 255);
const RULE = rgb(0xee / 255, 0xee / 255, 0xee / 255);
const CARD_FILL = rgb(0xfa / 255, 0xf8 / 255, 0xf5 / 255);
const PILL_BG = rgb(0xfd / 255, 0xf1 / 255, 0xde / 255);

const WORDMARK_BASE64 = "";

const DAY_LABELS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

const APPROACH_LABELS: Record<string, string> = {
  orange_base: "Orange Base",
  meal_bank: "KCPT Meal Bank",
  own: "My Own Meal",
};

function jsonResponse(body: Record<string, unknown>, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function requiredEnv(name: string): string | null {
  const value = Deno.env.get(name);
  return value && value.length > 0 ? value : null;
}

function isValidWeekStart(value: unknown): value is string {
  return typeof value === "string" && WEEK_START_PATTERN.test(value);
}

function formatWeekRange(weekStart: string): string {
  const [year, month, day] = weekStart.split("-").map(Number);
  const monday = new Date(Date.UTC(year, month - 1, day));
  const sunday = new Date(Date.UTC(year, month - 1, day + 6));
  const months = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
  ];
  const fmt = (d: Date) => months[d.getUTCMonth()] + " " + d.getUTCDate();
  return fmt(monday) + " - " + fmt(sunday);
}

function coerceNonNegotiables(raw: unknown): string[] {
  const names = ["", "", ""];
  if (!Array.isArray(raw)) return names;
  for (let i = 0; i < 3; i++) {
    const item = raw[i];
    if (typeof item === "string") names[i] = item;
    else if (
      item !== null &&
      typeof item === "object" &&
      !Array.isArray(item) &&
      typeof (item as Record<string, unknown>).name === "string"
    ) {
      names[i] = (item as Record<string, unknown>).name as string;
    }
  }
  return names;
}

function coerceString3(raw: unknown): string[] {
  const out = ["", "", ""];
  if (!Array.isArray(raw)) return out;
  for (let i = 0; i < 3; i++) {
    if (typeof raw[i] === "string") out[i] = raw[i] as string;
  }
  return out;
}

function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function avgNumbers(values: unknown): number | null {
  if (!Array.isArray(values)) return null;
  const nums = values.filter((v): v is number => typeof v === "number");
  if (nums.length === 0) return null;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

function formatCell(v: unknown): string {
  if (v === null || v === undefined) return "-";
  if (v === true) return "Y";
  if (typeof v === "boolean") return v ? "Y" : "-";
  if (typeof v === "number") {
    return Number.isInteger(v) ? String(v) : v.toFixed(1);
  }
  return String(v);
}

function fitCellSize(
  text: string,
  maxWidth: number,
  font: { widthOfTextAtSize: (t: string, s: number) => number },
  baseSize: number,
  minSize = 6,
): number {
  let size = baseSize;
  const pad = 2;
  while (size > minSize && font.widthOfTextAtSize(text, size) > maxWidth - pad) {
    size -= 0.5;
  }
  return size;
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "GET") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return jsonResponse({ error: "Unauthorized" }, 401);
  }

  const token = authHeader.slice("Bearer ".length);
  const supabaseUrl = requiredEnv("SUPABASE_URL");
  const supabaseAnonKey = requiredEnv("SUPABASE_ANON_KEY");
  if (!supabaseUrl || !supabaseAnonKey) {
    console.error("export-week-pdf: missing environment configuration");
    return jsonResponse({ error: "Unable to export PDF" }, 500);
  }

  const callerClient = createClient(supabaseUrl, supabaseAnonKey, {
    global: { headers: { Authorization: authHeader } },
    auth: { autoRefreshToken: false, persistSession: false },
  });

  const {
    data: { user },
    error: userError,
  } = await callerClient.auth.getUser(token);

  if (userError || !user) {
    return jsonResponse({ error: "Unauthorized" }, 401);
  }

  const url = new URL(req.url);
  const weekStart = url.searchParams.get("week_start");
  if (!isValidWeekStart(weekStart)) {
    return jsonResponse(
      { error: "week_start query param is required and must be YYYY-MM-DD" },
      400,
    );
  }

  const [planRes, trackerRes, measurementRes] = await Promise.all([
    callerClient
      .from("weekly_base_plans")
      .select("*")
      .eq("user_id", user.id)
      .eq("week_start", weekStart)
      .maybeSingle(),
    callerClient
      .from("weekly_tracker_entries")
      .select("*")
      .eq("user_id", user.id)
      .eq("week_start", weekStart)
      .maybeSingle(),
    callerClient
      .from("weight_measurements")
      .select("*")
      .eq("user_id", user.id)
      .eq("week_start", weekStart)
      .maybeSingle(),
  ]);

  if (planRes.error || trackerRes.error || measurementRes.error) {
    console.error("export-week-pdf: select failed", {
      plan: planRes.error,
      tracker: trackerRes.error,
      measurement: measurementRes.error,
    });
    return jsonResponse({ error: "Unable to load week data" }, 500);
  }

  const plan = planRes.data as Record<string, unknown> | null;
  const trackerRow = trackerRes.data as Record<string, unknown> | null;
  const measurement = measurementRes.data as Record<string, unknown> | null;

  const nonNegotiables = coerceNonNegotiables(trackerRow?.habits);
  const wins = coerceString3(trackerRow?.wins);
  const nextWeekFocus = coerceString3(trackerRow?.next_week_focus);
  const metrics = (trackerRow?.daily_metrics ?? null) as Record<
    string,
    unknown
  > | null;

  try {
    const pdfDoc = await PDFDocument.create();
    const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
    const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

    let page = pdfDoc.addPage([612, 792]);
    const margin = 48;
    const pageWidth = 612;
    const pageHeight = 792;
    const maxWidth = pageWidth - margin * 2;
    const labelColW = 78;
    const dayColW = 56;
    const avgColW = maxWidth - labelColW - dayColW * 7;

    const logoBytes = base64ToBytes(WORDMARK_BASE64);
    const logoImage = await pdfDoc.embedPng(logoBytes);
    const logoH = 20;
    const logoW = (logoImage.width / logoImage.height) * logoH;

    let y = pageHeight - margin;

    page.drawImage(logoImage, {
      x: margin,
      y: y - logoH,
      width: logoW,
      height: logoH,
    });

    const title = "Weekly Summary";
    const titleSize = 13;
    const titleW = fontBold.widthOfTextAtSize(title, titleSize);
    page.drawText(title, {
      x: pageWidth - margin - titleW,
      y: y - 11,
      size: titleSize,
      font: fontBold,
      color: DARK,
    });

    const weekRange = formatWeekRange(weekStart);
    const weekSize = 9;
    const weekW = font.widthOfTextAtSize(weekRange, weekSize);
    page.drawText(weekRange, {
      x: pageWidth - margin - weekW,
      y: y - 24,
      size: weekSize,
      font,
      color: MUTED,
    });

    y -= Math.max(logoH, 26) + 10;
    page.drawLine({
      start: { x: margin, y },
      end: { x: pageWidth - margin, y },
      thickness: 1.5,
      color: DARK,
    });
    y -= 18;

    const ensureSpace = (needed: number) => {
      if (y - needed < 48) {
        page = pdfDoc.addPage([612, 792]);
        y = pageHeight - margin;
      }
    };

    const drawSectionTitle = (title: string, badge?: string) => {
      ensureSpace(36);
      page.drawRectangle({
        x: margin,
        y: y - 3,
        width: 3,
        height: 12,
        color: ORANGE,
      });
      page.drawText(title, {
        x: margin + 10,
        y,
        size: 12,
        font: fontBold,
        color: DARK,
      });
      if (badge) {
        const badgeSize = 8;
        const padX = 8;
        const padY = 3;
        const badgeW = fontBold.widthOfTextAtSize(badge, badgeSize);
        const boxW = badgeW + padX * 2;
        const boxH = badgeSize + padY * 2;
        const boxX = margin + maxWidth - boxW;
        const boxY = y - 3;
        page.drawRectangle({
          x: boxX,
          y: boxY,
          width: boxW,
          height: boxH,
          color: PILL_BG,
        });
        page.drawText(badge, {
          x: boxX + padX,
          y: boxY + padY,
          size: badgeSize,
          font: fontBold,
          color: ORANGE_DARK,
        });
      }
      y -= 18;
    };

    const drawTextLine = (
      text: string,
      opts?: { bold?: boolean; size?: number; color?: ReturnType<typeof rgb> },
    ) => {
      const size = opts?.size ?? 10;
      const f = opts?.bold ? fontBold : font;
      const color = opts?.color ?? DARK;
      const words = text.split(" ");
      let line = "";
      for (const word of words) {
        const test = line ? line + " " + word : word;
        if (f.widthOfTextAtSize(test, size) > maxWidth) {
          ensureSpace(size + 6);
          page.drawText(line, { x: margin, y, size, font: f, color });
          y -= size + 4;
          line = word;
        } else {
          line = test;
        }
      }
      if (line) {
        ensureSpace(size + 6);
        page.drawText(line, { x: margin, y, size, font: f, color });
        y -= size + 4;
      }
    };

    const drawRightCell = (
      text: string,
      colRight: number,
      colWidth: number,
      baseSize: number,
      useBold: boolean,
      color: ReturnType<typeof rgb>,
    ) => {
      const f = useBold ? fontBold : font;
      const size = fitCellSize(text, colWidth, f, baseSize);
      const tw = f.widthOfTextAtSize(text, size);
      page.drawText(text, {
        x: colRight - tw,
        y,
        size,
        font: f,
        color,
      });
    };

    const drawPillarsTable = (dailyMetrics: Record<string, unknown>) => {
      const rowH = 17;
      const pillarKeys = [
        { key: "calories", label: "Calories" },
        { key: "protein", label: "Protein (g)" },
        { key: "water", label: "Water (L)" },
        { key: "steps", label: "Steps" },
        { key: "workout", label: "Workout" },
      ] as const;

      ensureSpace(rowH * (pillarKeys.length + 1) + 8);

      const dayRight = (i: number) => margin + labelColW + dayColW * (i + 1);
      const avgRight = margin + maxWidth;

      // Header
      for (let i = 0; i < 7; i++) {
        drawRightCell(DAY_LABELS[i], dayRight(i), dayColW, 8, false, MUTED);
      }
      drawRightCell("Avg", avgRight, avgColW, 8, false, MUTED);
      y -= 4;
      page.drawLine({
        start: { x: margin, y },
        end: { x: margin + maxWidth, y },
        thickness: 0.5,
        color: RULE,
      });
      y -= rowH - 4;

      for (const p of pillarKeys) {
        ensureSpace(rowH + 4);
        page.drawText(p.label, {
          x: margin,
          y,
          size: 9,
          font,
          color: DARK,
        });

        const series = dailyMetrics[p.key];
        for (let i = 0; i < 7; i++) {
          const raw = Array.isArray(series) ? series[i] : null;
          const text = formatCell(raw);
          const empty = text === "-";
          drawRightCell(
            text,
            dayRight(i),
            dayColW,
            9,
            false,
            empty ? MUTED : DARK,
          );
        }

        let avgText = "-";
        let avgMuted = true;
        if (p.key === "workout") {
          const count = Array.isArray(series)
            ? series.filter((v) => v === true).length
            : 0;
          avgText = count + "/7";
          avgMuted = false;
        } else {
          const avg = avgNumbers(series);
          if (avg != null) {
            avgMuted = false;
            avgText =
              p.key === "water" ? avg.toFixed(1) : String(Math.round(avg));
          }
        }
        drawRightCell(
          avgText,
          avgRight,
          avgColW,
          9,
          true,
          avgMuted ? MUTED : DARK,
        );

        y -= 4;
        page.drawLine({
          start: { x: margin, y },
          end: { x: margin + maxWidth, y },
          thickness: 0.5,
          color: RULE,
        });
        y -= rowH - 4;
      }
    };

    const wrapText = (
      text: string,
      width: number,
      f: typeof font,
      size: number,
    ): string[] => {
      const words = text.split(" ");
      const lines: string[] = [];
      let line = "";
      for (const word of words) {
        const test = line ? line + " " + word : word;
        if (f.widthOfTextAtSize(test, size) > width && line) {
          lines.push(line);
          line = word;
        } else {
          line = test;
        }
      }
      if (line) lines.push(line);
      return lines;
    };

    const drawNonNegotiableCards = (items: string[]) => {
      const cols = items.length;
      const gap = 8;
      const cardW = (maxWidth - gap * (cols - 1)) / cols;
      const cardH = 22;
      ensureSpace(cardH + 6);
      const top = y;
      for (let i = 0; i < cols; i++) {
        const x = margin + i * (cardW + gap);
        const text = items[i];
        const empty = !text;
        const label = empty ? "-" : text;
        page.drawRectangle({
          x,
          y: top - cardH,
          width: cardW,
          height: cardH,
          color: CARD_FILL,
        });
        const size = fitCellSize(label, cardW - 14, fontBold, 9.5);
        page.drawText(label, {
          x: x + 7,
          y: top - cardH / 2 - size / 2 + 1,
          size,
          font: fontBold,
          color: empty ? MUTED : DARK,
        });
      }
      y -= cardH + 6;
    };

    const approach = plan ? String(plan.nutrition_approach ?? "") : "";
    const approachBadge = plan
      ? APPROACH_LABELS[approach] ?? (approach || undefined)
      : undefined;
    drawSectionTitle("Food Plan", approachBadge);
    if (!plan) {
      drawTextLine("Not filled this week.", { color: MUTED });
    } else {
      const groups: { label: string; key: string }[] = [
        { label: "Breakfasts", key: "breakfasts" },
        { label: "Lunches", key: "lunches" },
        { label: "Trigger Snacks", key: "trigger_snacks" },
        { label: "Desserts", key: "desserts" },
      ];
      let any = false;
      for (const g of groups) {
        const items = Array.isArray(plan[g.key])
          ? (plan[g.key] as unknown[]).filter(
              (x) => typeof x === "string" && x.trim().length > 0,
            )
          : [];
        if (items.length === 0) continue;
        any = true;
        drawTextLine(g.label, { bold: true, size: 8.5, color: MUTED });
        drawTextLine(items.join(" - "));
        y -= 2;
      }
      const evening = Array.isArray(plan.evening_meals)
        ? (plan.evening_meals as Record<string, unknown>[])
        : [];
      const eveningFilled = evening.filter(
        (e) => typeof e.meal === "string" && e.meal.trim().length > 0,
      );
      if (eveningFilled.length > 0) {
        any = true;
        drawTextLine("Evening Meals", { bold: true, size: 8.5, color: MUTED });
        for (const e of eveningFilled) {
          const day = String(e.day ?? "");
          const meal = String(e.meal ?? "");
          const ap = String(e.approach ?? "");
          drawTextLine(
            "  - " + day + ": " + meal + " (" + (APPROACH_LABELS[ap] ?? ap) + ")",
          );
        }
      }
      if (!any) drawTextLine("No meals set this week.", { color: MUTED });
    }
    y -= 12;

    drawSectionTitle("Non-Negotiables");
    if (!trackerRow) {
      drawNonNegotiableCards(["", "", ""]);
    } else {
      drawNonNegotiableCards(nonNegotiables.map((s) => s.trim()));
    }
    y -= 6;

    drawSectionTitle("Daily Numbers");
    if (!trackerRow || !metrics) {
      drawTextLine("No daily numbers recorded this week.", { color: MUTED });
    } else {
      drawPillarsTable(metrics);
    }
    y -= 6;

    // --- Sunday Reset (left) + Measurements (right), side by side ---
    const twoColGap = 18;
    const colWidth = (maxWidth - twoColGap) / 2;
    const rightX = margin + colWidth + twoColGap;

    const winList = wins.map((s) => s.trim()).filter(Boolean);
    const focusList = nextWeekFocus.map((s) => s.trim()).filter(Boolean);

    type LeftLine = {
      text: string;
      bold?: boolean;
      size?: number;
      color?: ReturnType<typeof rgb>;
    };
    const leftLines: LeftLine[] = [];
    if (!trackerRow || (winList.length === 0 && focusList.length === 0)) {
      leftLines.push({ text: "Not completed this week", color: MUTED });
    } else {
      leftLines.push({ text: "Wins", bold: true, size: 8.5, color: MUTED });
      if (winList.length === 0) {
        leftLines.push({ text: "-", color: MUTED });
      } else {
        for (const w of winList) {
          for (const ln of wrapText("- " + w, colWidth, font, 9.5)) {
            leftLines.push({ text: ln, size: 9.5 });
          }
        }
      }
      leftLines.push({
        text: "Next Week Focus",
        bold: true,
        size: 8.5,
        color: MUTED,
      });
      if (focusList.length === 0) {
        leftLines.push({ text: "-", color: MUTED });
      } else {
        for (const w of focusList) {
          for (const ln of wrapText("- " + w, colWidth, font, 9.5)) {
            leftLines.push({ text: ln, size: 9.5 });
          }
        }
      }
    }

    const measureFields: { key: string; label: string; unit: string }[] = [
      { key: "weight", label: "Weight", unit: "lbs" },
      { key: "waist", label: "Waist", unit: "in" },
      { key: "hips", label: "Hips", unit: "in" },
      { key: "arm", label: "Arm", unit: "in" },
      { key: "thigh", label: "Thigh", unit: "in" },
      { key: "calve", label: "Calve", unit: "in" },
    ];
    const measureCards = measureFields.map((f) => {
      const v = measurement?.[f.key];
      const has = typeof v === "number";
      return {
        label: f.label,
        value: has ? v + " " + f.unit : "-",
        muted: !has,
      };
    });

    const headerH = 18;
    const leftHeight =
      headerH + leftLines.reduce((h, l) => h + (l.size ?? 9.5) + 4, 0);

    const rightCols = 2;
    const rightGap = 10;
    const rightCardW = (colWidth - rightGap * (rightCols - 1)) / rightCols;
    const rightCardH = 32;
    const rightRows = Math.ceil(measureCards.length / rightCols);
    const rightHeight = headerH + rightRows * (rightCardH + rightGap);

    ensureSpace(Math.max(leftHeight, rightHeight) + 8);
    const sectionTop = y;

    page.drawRectangle({
      x: margin,
      y: sectionTop - 3,
      width: 3,
      height: 12,
      color: ORANGE,
    });
    page.drawText("Sunday Reset", {
      x: margin + 10,
      y: sectionTop,
      size: 12,
      font: fontBold,
      color: DARK,
    });
    let leftY = sectionTop - headerH;
    for (const l of leftLines) {
      const size = l.size ?? 9.5;
      const f = l.bold ? fontBold : font;
      page.drawText(l.text, {
        x: margin,
        y: leftY,
        size,
        font: f,
        color: l.color ?? DARK,
      });
      leftY -= size + 4;
    }

    page.drawRectangle({
      x: rightX,
      y: sectionTop - 3,
      width: 3,
      height: 12,
      color: ORANGE,
    });
    page.drawText("Measurements", {
      x: rightX + 10,
      y: sectionTop,
      size: 12,
      font: fontBold,
      color: DARK,
    });
    const rightContentTop = sectionTop - headerH;
    for (let i = 0; i < measureCards.length; i++) {
      const col = i % rightCols;
      const row = Math.floor(i / rightCols);
      const cx = rightX + col * (rightCardW + rightGap);
      const top = rightContentTop - row * (rightCardH + rightGap);
      const bottom = top - rightCardH;
      page.drawRectangle({
        x: cx,
        y: bottom,
        width: rightCardW,
        height: rightCardH,
        color: CARD_FILL,
      });
      page.drawText(measureCards[i].label, {
        x: cx + 8,
        y: top - 12,
        size: 8,
        font,
        color: MUTED,
      });
      page.drawText(measureCards[i].value, {
        x: cx + 8,
        y: top - 27,
        size: 11,
        font: fontBold,
        color: measureCards[i].muted ? MUTED : DARK,
      });
    }
    const rightY = rightContentTop - rightRows * (rightCardH + rightGap);

    y = Math.min(leftY, rightY) - 12;

    const footerText = "Consistency Beats Perfection";
    const footerH = 22;
    ensureSpace(footerH + 8);
    page.drawRectangle({
      x: 0,
      y: y - footerH + 6,
      width: pageWidth,
      height: footerH,
      color: ORANGE_DARK,
    });
    const footerSize = 11;
    const footerW = fontBold.widthOfTextAtSize(footerText, footerSize);
    page.drawText(footerText, {
      x: (pageWidth - footerW) / 2,
      y: y - footerH + 6 + (footerH - footerSize) / 2 + 1,
      size: footerSize,
      font: fontBold,
      color: rgb(1, 1, 1),
    });

    const pdfBytes = await pdfDoc.save();
    return new Response(pdfBytes, {
      status: 200,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/pdf",
        "Content-Disposition":
          'attachment; filename="kcpt-week-' + weekStart + '.pdf"',
      },
    });
  } catch (err) {
    console.error("export-week-pdf: generate failed", err);
    return jsonResponse({ error: "Unable to generate PDF" }, 500);
  }
});
